void Solver::restart() {
    // Reset LBD statistics completely
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    for (int i = 0; i < 50; ++i) lbd_queue[i] = 0;

    // Backtrack to root level
    backtrack(0);

    // Rephase variables with a new distribution
    int r = rand() % 100;
    if (r < 50) { // 50% keep the best local phase
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 80) { // 30% invert the best local phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else { // 20% assign random phase
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // Optionally raise the restart threshold to delay immediate rephasing
    threshold = std::max(threshold, (int)trail.size());
}
